    auto [d, v] = pq.top(); pq.pop();
    if (d > dist[v]) continue;              // stale entry skip
    for (auto [u, w] : adj[v])
        if (dist[v] + w < dist[u]) {
            dist[u] = dist[v] + w;
            pq.push({dist[u], u});          // lazy push (no decrease-key)
        }
