    d, v = heapq.heappop(pq)
    if d > dist[v]: continue          # stale entry skip
    for u, w in adj[v]:
        if dist[v] + w < dist[u]:
            dist[u] = dist[v] + w
            heapq.heappush(pq, (dist[u], u))

